<?php
/** Host must authenticate BEFORE including this file. $monitor is an EWMonitor. */
function ew_e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function ew_time(?string $v):string{if(!$v)return '暂无记录';return (new DateTimeImmutable($v,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Shanghai'))->format('Y-m-d H:i:s');}
function ew_table(array $headers,array $rows,string $empty='当前条件下暂无记录'):void{
 if(count($headers)>4)echo '<p class="ew-scroll-hint hint">表格可左右滑动查看全部列。</p>';
 echo '<div class="table-wrap '.(count($headers)<=4?'ew-simple'.(count($headers)===2?' ew-pair':''):'ew-wide').'" tabindex="0" aria-label="数据表格"><table><thead><tr>';foreach($headers as $h)echo '<th>'.ew_e($h).'</th>';echo '</tr></thead><tbody>';
 foreach($rows as $row){echo '<tr>';foreach($row as $v){echo '<td>';if(is_array($v)){echo '<span class="ew-cell-title">'.ew_e($v[0]).'</span><small class="ew-cell-detail">'.ew_e($v[1]??'').'</small>';}else{if(is_string($v)&&preg_match('/^\d{4}-\d\d-\d\d[T ]\d\d:/',$v))$v=ew_time($v);echo ew_e($v===''?'—':($v??'—'));}echo '</td>';}echo '</tr>';}
 if(!$rows)echo '<tr><td colspan="'.count($headers).'" class="empty">'.ew_e($empty).'</td></tr>';echo '</tbody></table></div>';
}
function ew_url(array $extra=[]):string{
 $query=array_intersect_key($_GET,array_flip(['scope','days','source','bot','verify','view']));$query=array_merge($query,['tab'=>'monitor'],$extra);
 if(in_array($query['view']??'overview',['overview','visits','health'],true))foreach(['source','bot','verify'] as $k)unset($query[$k]);
 return '?'.http_build_query($query);
}
function ew_paged_table(array $headers,array $rows,string $key,int $size=10,string $empty='当前条件下暂无记录'):void{
 $total=count($rows);$pages=max(1,(int)ceil($total/$size));$page=max(1,min($pages,(int)($_GET[$key]??1)));ew_table($headers,array_slice($rows,($page-1)*$size,$size),$empty);
 if($total){echo '<div class="pagination">共 '.$total.' 条 · 第 '.$page.' / '.$pages.' 页';foreach(['上一页'=>$page-1,'下一页'=>$page+1] as $label=>$n)if($n>=1&&$n<=$pages)echo '<a class="action-neutral" href="'.ew_e(ew_url([$key=>$n])).'">'.$label.'</a>';echo '</div>';}
}
function ew_referrals(EWMonitor $monitor,string $scope,string $start):array{
 $merged=[];foreach($monitor->rows("SELECT referral,COUNT(*) pv FROM ew_events WHERE scope=? AND observed_at>=? AND event_name='pageview' GROUP BY referral",[$scope,$start]) as $r){$name=EWMonitor::canonicalReferral($r['referral'],$monitor->rules);$merged[$name]=($merged[$name]??0)+(int)$r['pv'];}arsort($merged);$rows=[];foreach($merged as $name=>$n)$rows[]=[$name,$n];return $rows;
}
function ew_page(string $path,EWMonitor $monitor):array{return [$monitor->catalog[$path]??'历史页面 / 未匹配目录',$path];}
function ew_metric(string $key,string $label,int $value,string $explain,string $url):void{echo '<a class="panel ew-metric" data-metric="'.ew_e($key).'" href="'.ew_e($url).'"><span>'.ew_e($label).'</span><strong data-value="'.$value.'">'.number_format($value).'<small>次</small></strong><p>'.ew_e($explain).'</p><b>查看详情 →</b></a>';}
function ew_status(int $s):string{return match(true){$s===404=>'页面不存在（404）',$s>=500=>'服务器出错（'.$s.'）',$s===403=>'访问被拒绝（403）',$s>=400=>'访问未成功（'.$s.'）',$s>=300=>'跳转或缓存响应（'.$s.'）',default=>'正常响应（'.$s.'）'};}
$vnames=['official_ip'=>'来源已核验','unmatched'=>'来源未匹配，待核实','unverified'=>'仅自报身份，待核实','historical_unknown'=>'缺少当时的核验资料','stale'=>'核验资料已过期','ip_missing'=>'缺少来源地址','ambiguous'=>'身份信息冲突','invalid_evidence'=>'核验资料无效','not_applicable'=>'普通访问'];
$views=['overview'=>'数据概览','requests'=>'AI 来访','coverage'=>'页面抓取','visits'=>'访客与点击','health'=>'技术详情'];$view=isset($views[$_GET['view']??''])?$_GET['view']:'overview';
$scope=in_array($_GET['scope']??'',['production','preview'],true)?$_GET['scope']:$monitor->scope();
$days=in_array((int)($_GET['days']??7),[1,7,30,90],true)?(int)($_GET['days']??7):7;
$tz=new DateTimeZone('Asia/Shanghai');$start=(new DateTimeImmutable('today',$tz))->modify('-'.($days-1).' days')->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');
$source=preg_match('/^[a-zA-Z0-9_-]{1,64}$/',$_GET['source']??'php')?($_GET['source']??'php'):'php';
$bot=substr($_GET['bot']??'',0,80);$verify=array_key_exists($_GET['verify']??'',$vnames)?$_GET['verify']:'';
if(in_array($view,['overview','visits','health'],true)){$source='php';$bot='';$verify='';}
$where='scope=? AND source=? AND observed_at>=?';$params=[$scope,$source,$start];if($bot!==''){$where.=' AND bot=?';$params[]=$bot;}if($verify){$where.=' AND verification=?';$params[]=$verify;}
$ai=EWMonitor::aiPredicate();
if(isset($_GET['export'])){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="monitor-requests.csv"');header('Cache-Control: private, no-store');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,['UTC时间','路径','方法','状态码','爬虫','平台','用途','核验','IP快照哈希','身份规则版本','来源','范围'],',','"','');foreach($monitor->rows("SELECT observed_at,path,method,status,bot,provider,purpose,verification,rule_hash,rule_version,source,scope FROM ew_requests WHERE $where ORDER BY id DESC LIMIT 5000",$params) as $r){foreach($r as &$x)if(preg_match('/^[=+@\-\t\r\n]/',(string)$x))$x="'".$x;unset($x);fputcsv($f,array_values($r),',','"','');}exit;}
$counts=$monitor->rows("SELECT COUNT(*) total,SUM($ai) ai,SUM(($ai) AND verification='official_ip') verified,SUM(status>=400) errors,MAX(observed_at) latest FROM ew_requests WHERE $where",$params)[0];
$aiReferrals=EWMonitor::referralLabels($monitor->rules);$refSql=implode(',',array_fill(0,count($aiReferrals),'?'));
$events=$monitor->rows("SELECT SUM(event_name='pageview') pv,COUNT(DISTINCT CASE WHEN event_name='pageview' THEN visitor END) uv,SUM(event_name<>'pageview') actions,SUM(event_name='pageview' AND referral IN ($refSql)) ai_pv FROM ew_events WHERE scope=? AND observed_at>=?",array_merge($aiReferrals,[$scope,$start]))[0];
$pending=max(0,(int)($counts['ai']??0)-(int)($counts['verified']??0));
$sources=array_column($monitor->rows('SELECT DISTINCT source FROM ew_requests ORDER BY source LIMIT 100'),'source');if(!in_array('php',$sources,true))$sources[]='php';
?><div class="ew-report"><nav class="ew-tabs" aria-label="监测分区"><?php foreach($views as $key=>$label):?><a href="<?=ew_e(ew_url(['view'=>$key]))?>" <?=$view===$key?'aria-current="page"':''?>><?=$label?></a><?php endforeach;?></nav>
<section class="panel ew-filter-panel"><div class="ew-scope"><span class="ew-scope-badge"><?=$scope==='preview'?'本机预览数据':'正式站数据'?></span><span>北京时间<?=$view==='health'?' · 当前状态':($days===1?' · 今天':' · 近 '.$days.' 天')?></span></div>
<?php if($scope==='preview'):?><p class="ew-context">这里包含本机浏览和测试记录，用于检查功能，不能用来判断真实获客。</p><?php elseif($monitor->config['preview']):?><p class="ew-context">当前网站尚为本机预览；这里单独查看正式站记录，不会把测试量算进去。</p><?php endif;?>
<form class="filters ew-filters" method="get"><input type="hidden" name="tab" value="monitor"><input type="hidden" name="view" value="<?=$view?>"><label>查看范围<select name="scope" aria-label="查看范围"><option value="production" <?=$scope==='production'?'selected':''?>>正式站</option><option value="preview" <?=$scope==='preview'?'selected':''?>>本机预览</option></select></label><?php if($view!=='health'):?><label>时间<select name="days" aria-label="时间"><?php foreach([1=>'今天',7=>'近 7 天',30=>'近 30 天',90=>'近 90 天'] as $k=>$label):?><option value="<?=$k?>" <?=$days===$k?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><?php endif;?><button class="action-search">查找</button>
<?php if(in_array($view,['requests','coverage'],true)):?><details class="ew-advanced" <?=$bot!==''||$verify!==''||$source!=='php'?'open':''?>><summary>更多筛选<?=$bot!==''||$verify!==''||$source!=='php'?'（已启用）':''?></summary><div class="ew-extra-fields"><label>记录来自<select name="source" aria-label="记录来自"><?php foreach($sources as $src):?><option value="<?=ew_e($src)?>" <?=$src===$source?'selected':''?>><?=ew_e($src==='php'?'网站应用':$src)?></option><?php endforeach;?></select></label><label>机器人名称<input name="bot" value="<?=ew_e($bot)?>" placeholder="例如 GPTBot"></label><label>来源核验<select name="verify" aria-label="来源核验"><option value="">全部</option><?php foreach($vnames as $key=>$label):?><option value="<?=$key?>" <?=$verify===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label></div></details><?php endif;?></form></section>
<?php if($view==='overview'):?>
<div class="ew-stats stats">
<?php ew_metric('pv','网站浏览',(int)($events['pv']??0),'页面被浏览的次数，同一人可浏览多次。',ew_url(['view'=>'visits']));
ew_metric('verified','已核验的 AI 来访',(int)($counts['verified']??0),'来源符合官方清单；另有 '.$pending.' 次待核实。',ew_url(['view'=>'requests']));
ew_metric('ai_pv','从 AI 带来的浏览',(int)($events['ai_pv']??0),'带有 AI 平台来源信息的页面浏览。',ew_url(['view'=>'visits']));
ew_metric('actions','联系 / 下载点击',(int)($events['actions']??0),'电话、邮箱或资料点击，不是咨询成功数。',ew_url(['view'=>'visits']));?>
</div>
<section class="panel ew-reading"><h2>这组数据怎么看</h2><p><?php if((int)$counts['verified']>0):?>已记录到来源核验通过的 AI 访问。可到“页面抓取”查看它们成功读取了哪些页面。<?php elseif($pending>0):?>有 <?=$pending?> 次访问自报 AI 身份，但来源尚未核验通过，暂不算入“已核验的 AI 来访”。<?php else:?>当前范围还没有记录到已核验的 AI 来访，暂时无法判断 AI 对网站的关注情况。<?php endif;?></p><p class="hint">AI 来抓取网页，与用户从 AI 链接进入网站是两件事；两者都不能直接证明内容已被收录、引用或带来客户。</p></section>
<div class="ew-columns"><section class="panel"><div class="ew-heading"><h2>每天有多少次浏览</h2><span class="hint"><?=$days>14?'显示最近 14 天':'所选时间范围'?></span></div>
<?php $trend=$monitor->rows("SELECT DATE(DATE_ADD(observed_at,INTERVAL 8 HOUR)) day,COUNT(*) total FROM ew_events WHERE scope=? AND observed_at>=? AND event_name='pageview' GROUP BY day",[$scope,$start]);$trendMap=array_column($trend,'total','day');$chart=[];for($i=min($days,14)-1;$i>=0;$i--){$d=(new DateTimeImmutable('today',$tz))->modify('-'.$i.' days')->format('Y-m-d');$chart[$d]=(int)($trendMap[$d]??0);}$max=max(1,...array_values($chart));?>
<div class="ew-chart" role="list" aria-label="每日浏览次数"><?php foreach($chart as $d=>$n):?><div class="ew-chart-column" role="listitem" aria-label="<?=ew_e($d.'，'.$n.' 次浏览')?>"><span class="ew-chart-value"><?=$n?></span><div class="ew-chart-track"><span style="height:<?=round($n/$max*100,2)?>%"></span></div><small><?=substr($d,5)?></small></div><?php endforeach;?></div><p class="hint">只统计浏览器回传的浏览记录，不是服务器请求总量。</p></section>
<section class="panel"><div class="ew-heading"><h2>大家在看什么</h2><a class="action-search" href="<?=ew_e(ew_url(['view'=>'visits']))?>">查看详情</a></div><?php $popular=$monitor->rows("SELECT path,COUNT(*) total FROM ew_events WHERE scope=? AND observed_at>=? AND event_name='pageview' GROUP BY path ORDER BY total DESC,path LIMIT 5",[$scope,$start]);ew_table(['页面','浏览次数'],array_map(fn($r)=>[ew_page($r['path'],$monitor),$r['total']],$popular),'暂无浏览记录；正式上线后可在这里查看热门页面。');?></section></div>
<section class="panel ew-followup"><div><h2>访问是否有问题</h2><p><?=(int)$counts['errors']>0?'记录到 '.(int)$counts['errors'].' 次未成功响应，可查看具体页面和原因。':'当前条件下未记录到失败响应。'?><?=$scope==='preview'?' 本机测试也可能主动访问不存在的页面。':''?></p><p class="hint">概览的 AI 来访与失败响应采用“网站应用”记录，其他日志来源在详细筛选中单独查看。</p></div><a class="action-search" href="<?=ew_e(ew_url(['view'=>'requests']))?>#ew-errors">查看访问问题</a></section>
<?php endif;if($view==='requests'):?>
<section class="panel"><details><summary>平台覆盖与识别范围</summary><p class="hint">清单包含主流国内外助手。未接入专用身份规则表示无法确认爬虫，不表示访问为零；来源浏览也依赖浏览器提供来源信息。规则资料核对日期：<?=ew_e($monitor->rules['version']??'未记录')?>。</p><?php ew_table(['平台','可识别请求','统计范围'],array_map(fn($p)=>[$p['name'],implode('、',$p['bots'])?:'暂无法确认',$p['coverage']],$monitor->rules['platforms']??[]));?></details></section>

<section class="panel"><h2>已识别的 AI 请求</h2><p>来源已核验 <strong><?=(int)($counts['verified']??0)?></strong> 次 · 待核实 <strong><?=$pending?></strong> 次</p><p class="hint">“已核验”表示来源地址符合官方清单；“待核实”表示仅有身份声明或核验资料不足。训练、搜索、用户触发与浏览器代理分列；不能把训练抓取当搜索采用。来访不等于成功读取页面。</p><?php $rs=$monitor->rows("SELECT bot,provider,purpose,verification,COUNT(*) total,MAX(observed_at) recent FROM ew_requests WHERE $where AND $ai GROUP BY bot,provider,purpose,verification ORDER BY total DESC LIMIT 100",$params);$purposes=['training'=>'训练资料抓取','search'=>'搜索抓取','user'=>'用户触发访问','agent'=>'浏览器代理访问'];ew_paged_table(['平台 / 机器人','来源判断','来访次数','最近来访'],array_map(fn($r)=>[[$r['provider']?:'未识别平台',$r['bot'].' · '.($purposes[$r['purpose']]??'未知用途')],$vnames[$r['verification']]??'待核实',$r['total'],$r['recent']],$rs),'bots_page',10,'当前条件下暂无 AI 来访记录；不代表平台一定没有访问。');?></section>
<section class="panel" id="ew-errors"><h2>访问问题</h2><p class="hint">这里包括普通访问和机器人访问。页面不存在可能来自旧链接或测试；有记录不等于网站整体故障。</p><?php ew_paged_table(['页面','情况','次数'],array_map(fn($r)=>[ew_page($r['path'],$monitor),ew_status((int)$r['status']),$r['total']],$monitor->rows("SELECT path,status,COUNT(*) total FROM ew_requests WHERE $where AND status>=400 GROUP BY path,status ORDER BY total DESC LIMIT 30",$params)),'errors_page',10,'当前条件下未记录到失败响应。');?></section>
<section class="panel"><details class="ew-technical" <?=isset($_GET['page'])?'open':''?>><summary>全部访问明细（供排查） · <?=(int)$counts['total']?> 条</summary><div id="ew-requests"><div class="ew-heading"><p class="hint">包含普通访问与机器人；请求次数不是访客人数。导出当前筛选下最多 5000 条。</p><a class="action-search" href="<?=ew_e(ew_url(['view'=>'requests','export'=>1]))?>">导出记录</a></div><?php $requestPages=max(1,(int)ceil((int)$counts['total']/20));$page=max(1,min($requestPages,(int)($_GET['page']??1)));$offset=($page-1)*20;$rs=$monitor->rows("SELECT observed_at,path,method,status,bot,verification,duration_ms FROM ew_requests WHERE $where ORDER BY id DESC LIMIT 20 OFFSET $offset",$params);ew_table(['北京时间','路径','方法','响应','机器人','来源判断','耗时（毫秒）'],array_map(fn($r)=>[$r['observed_at'],$r['path'],$r['method'],ew_status((int)$r['status']),$r['bot']?:'普通访问',$vnames[$r['verification']]??'待核实',$r['duration_ms']],$rs));?><div class="pagination">共 <?=(int)$counts['total']?> 条 · 第 <?=$page?> / <?=$requestPages?> 页<?php foreach(['上一页'=>$page-1,'下一页'=>$page+1] as $label=>$n)if($n>0&&$n<=$requestPages):?><a class="action-neutral" href="<?=ew_e(ew_url(['page'=>$n]))?>#ew-requests"><?=$label?></a><?php endif;?></div></div></details></section>
<?php endif;if($view==='coverage'):?>
<section class="panel" id="ew-coverage"><h2>哪些页面向 AI 返回成功响应</h2><p class="hint">只计算返回 GET 200 的已识别 AI 请求；HTTP 成功响应不保证正文完整或已被 AI 理解。抓取记录不等于平台已收录或引用。</p>
<?php $group=$monitor->rows("SELECT path,SUM(($ai) AND method='GET' AND status=200) claims,SUM(($ai) AND method='GET' AND status=200 AND verification='official_ip') verified,MAX(CASE WHEN ($ai) AND method='GET' AND status=200 THEN observed_at END) recent FROM ew_requests WHERE $where GROUP BY path",$params);$map=array_column($group,null,'path');$cv=[];$covered=0;foreach($monitor->catalog as $path=>$title){$m=$map[$path]??[];$verified=(int)($m['verified']??0);$claims=(int)($m['claims']??0);if($verified>0)$covered++;$state=$verified>0?'已核验抓取':($claims>0?'有抓取记录，来源待核实':'尚未记录到抓取');$cv[]=[[$title,$path],$state,[$verified.' 次已核验',max(0,$claims-$verified).' 次待核实'],$m['recent']??'暂无记录'];}$total=count($cv);?>
<div class="ew-coverage-count"><strong><?=$covered?><small> / <?=$total?> 页</small></strong><span>有已核验的成功抓取记录</span></div><progress max="<?=max(1,$total)?>" value="<?=$covered?>" aria-label="有已核验抓取记录的页面占比"></progress>
<?php if($scope==='production'&&$monitor->config['preview']):?><p class="hint">页面目录来自当前预览版本，正式发布前需复核。</p><?php endif;ew_paged_table(['页面','抓取情况','成功读取次数','最近成功读取'],array_slice($cv,0,500),'coverage_page');if($total>500)echo '<p class="hint">这里只展示前 500 页，请联系维护人员导出全量目录。</p>';?><details class="ew-technical"><summary>统计说明</summary><p class="hint">当前目录中的页面才进入分母，已删除页面不计入。HEAD、304 和失败响应不计成功读取；最近时间包括来源待核实的成功请求。上方日志来源、机器人和来源核验筛选均生效。</p></details></section>
<?php endif;if($view==='visits'):?>
<section class="panel" id="ew-visits"><h2>访客从哪里来、做了什么</h2><p>网站浏览 <strong><?=(int)($events['pv']??0)?></strong> 次 · 从 AI 带来的浏览 <strong><?=(int)($events['ai_pv']??0)?></strong> 次 · 联系 / 下载点击 <strong><?=(int)($events['actions']??0)?></strong> 次</p><p class="hint">浏览次数不是人数，点击也不等于咨询成功。来源未提供时，无法判断来自哪个渠道。</p>
<h3>浏览来源</h3><?php ew_paged_table(['本次页面的来源','浏览次数'],ew_referrals($monitor,$scope,$start),'referral_page',10,'当前范围还没有浏览来源记录。');?>
<h3>联系与下载</h3><?php $enames=['download_brief'=>'点击下载资料','click_phone'=>'点击电话','click_email'=>'点击邮箱'];$rs=$monitor->rows("SELECT event_name,path,COUNT(*) total FROM ew_events WHERE scope=? AND observed_at>=? AND event_name<>'pageview' GROUP BY event_name,path ORDER BY total DESC LIMIT 50",[$scope,$start]);ew_paged_table(['操作','所在页面','点击次数'],array_map(fn($r)=>[$enames[$r['event_name']]??$r['event_name'],ew_page($r['path'],$monitor),$r['total']],$rs),'events_page',10,'尚未记录到联系或下载点击。');?>
<h3>浏览了哪些页面</h3><?php $rs=$monitor->rows("SELECT path,COUNT(*) total FROM ew_events WHERE scope=? AND observed_at>=? AND event_name='pageview' GROUP BY path ORDER BY total DESC LIMIT 100",[$scope,$start]);ew_paged_table(['页面','浏览次数'],array_map(fn($r)=>[ew_page($r['path'],$monitor),$r['total']],$rs),'visits_page');?>
